-- PT105-S1-Q4. Batch 11.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT105-S1-Q4$batch11$ AND q.stimulus=$batch11$In an experiment testing whether hyperactivity is due to a brain abnormality, the brain activity of 25 hyperactive adults was compared to the brain activity of 25 adults who were not hyperactive. The tests revealed that the hyperactive adults had much less brain activity in the premotor cortex, a region of the brain believed to control action, than did the nonhyperactive adults. The experimenters concluded that diminished activity in the premotor cortex is one cause of hyperactivity.$batch11$ AND q.prompt=$batch11$Which one of the following, if true, most undermines the conclusion drawn by the experimenters?$batch11$ AND q.correct_choice=$batch11$D$batch11$) THEN RAISE EXCEPTION 'Question changed: PT105-S1-Q4'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch11$PT105-S1-Q4$batch11$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT105-S1-Q4'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT105-S1-Q4$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Conclusion$batch11$, $batch11$Low activity in the premotor cortex is one cause of hyperactivity.$batch11$), (1, $batch11$Evidence$batch11$, $batch11$Hyperactive adults had much less premotor activity than adults who weren't hyperactive.$batch11$), (2, $batch11$Evaluate$batch11$, $batch11$This is a correlation turned into a cause. Something else could explain the low brain activity. If the hyperactive group differs in some other way that lowers brain activity, the hyperactivity may not come from the brain difference at all.$batch11$), (3, $batch11$Goal$batch11$, $batch11$Find another explanation for the hyperactive group's lower brain activity.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT105-S1-Q4$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$The study measured the adults themselves, not their children.$batch11$), ($batch11$B$batch11$, $batch11$Varied severity doesn't explain why the whole group had lower activity.$batch11$), ($batch11$C$batch11$, $batch11$The designers being absent doesn't show the tests were done wrong.$batch11$), ($batch11$D$batch11$, $batch11$Every hyperactive adult took a drug that depresses brain activity, and no one in the other group did. The drug, not hyperactivity's cause, could explain the low activity.$batch11$), ($batch11$E$batch11$, $batch11$Why the test excluded children doesn't affect the result for adults.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT105-S1-Q4$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
